            TempString = ""
            Try
                 Character = DataString(Count)
                 While Character <> ";"
                      TempString = TempString + Character
                      Count = Count + 1
                      Character = DataString(Count)
                 End While
                 SplitDataArray(LastElement) = TempString
                 LastElement = LastElement + 1
            Catch
                 Console.WriteLine("No more character")
            End Try
            Count = Count + 1
       Next
       Return SplitDataArray
   End Function
